package com.bank.window;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.logging.Logger;

// Rotates Rajesh's rolling balance window in place for National Bank of India.
public class WindowRotator {
    private static final Logger log = Logger.getLogger(WindowRotator.class.getName());

    // Right-rotate by k using the triple-reversal trick. O(n), O(1).
    public void rotateRight(BigDecimal[] window, int k) {
        if (window == null || window.length < 2) return;
        int n = window.length;
        k = ((k % n) + n) % n;              // normalise k (handles k>n and k<0)
        if (k == 0) {
            log.fine("Rotation by 0 is a no-op");
            return;
        }
        reverse(window, 0, n - 1);          // reverse the whole array
        reverse(window, 0, k - 1);          // reverse the first k
        reverse(window, k, n - 1);          // reverse the rest
        log.info(() -> "Rotated right by " + ((k) ) + ": " + Arrays.toString(window));
    }

    // Two-pointer in-place reverse of window[from..to].
    private void reverse(BigDecimal[] window, int from, int to) {
        while (from < to) {
            BigDecimal temp = window[from];
            window[from] = window[to];
            window[to] = temp;
            from++;
            to--;
        }
    }
}
