package com.bank.window;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: rotate Rajesh's balance window by normal and oversized k.
public class WindowDemo {
    private static final Logger log = Logger.getLogger(WindowDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    private static BigDecimal bd(String s) { return new BigDecimal(s); }

    public static void main(String[] args) {
        WindowRotator rotator = new WindowRotator();

        // Rajesh (SAV2001) last-5-day closing balances.
        BigDecimal[] window = { bd("100"), bd("200"), bd("300"), bd("400"), bd("500") };
        log.info(() -> "Before: " + Arrays.toString(window));

        rotator.rotateRight(window, 2);
        log.info(() -> "After rotateRight(2): " + Arrays.toString(window));

        // Oversized k: 7 % 5 = 2, same as rotating by 2 again.
        rotator.rotateRight(window, 7);
        log.info(() -> "After rotateRight(7): " + Arrays.toString(window));
    }
}
